import{_ as e,o as a,c as r,a3 as i}from"./chunks/framework.CHYjUC2p.js";const u=JSON.parse('{"title":"Technology Choices & Exhaustive Trade-Off Comparisons","description":"","frontmatter":{},"headers":[],"relativePath":"04-tech-comparisons.md","filePath":"04-tech-comparisons.md"}'),l={name:"04-tech-comparisons.md"};function o(n,t,s,d,c,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="technology-choices-exhaustive-trade-off-comparisons" tabindex="-1">Technology Choices &amp; Exhaustive Trade-Off Comparisons <a class="header-anchor" href="#technology-choices-exhaustive-trade-off-comparisons" aria-label="Permalink to &quot;Technology Choices &amp; Exhaustive Trade-Off Comparisons&quot;">​</a></h1><h2 id="_1-proxy-core-language-runtime" tabindex="-1">1. Proxy Core Language &amp; Runtime <a class="header-anchor" href="#_1-proxy-core-language-runtime" aria-label="Permalink to &quot;1. Proxy Core Language &amp; Runtime&quot;">​</a></h2><h3 id="chosen-typescript-node-js-native-http-streams" tabindex="-1">Chosen: TypeScript &amp; Node.js Native HTTP Streams <a class="header-anchor" href="#chosen-typescript-node-js-native-http-streams" aria-label="Permalink to &quot;Chosen: TypeScript &amp; Node.js Native HTTP Streams&quot;">​</a></h3><ul><li><strong>File References</strong>: <code>src/proxy/index.ts</code>, <code>src/proxy/stream.ts</code></li><li><strong>Role in Project</strong>: Implements asynchronous reverse proxy listener, stream piping, and RFC 9111 rules.</li></ul><h3 id="exhaustive-alternatives-comparison" tabindex="-1">Exhaustive Alternatives Comparison <a class="header-anchor" href="#exhaustive-alternatives-comparison" aria-label="Permalink to &quot;Exhaustive Alternatives Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Evaluation Metric</th><th style="text-align:left;">TypeScript / Node.js Streams (Chosen)</th><th style="text-align:left;">Rust (Actix-Web / Hyper)</th><th style="text-align:left;">Go (<code>net/http</code>)</th><th style="text-align:left;">C++ (Nginx / Envoy)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>I/O Model</strong></td><td style="text-align:left;">Non-blocking Libuv event loop</td><td style="text-align:left;">Async Tokio epoll event loop</td><td style="text-align:left;">Goroutine-per-connection</td><td style="text-align:left;">Event-driven epoll threads</td></tr><tr><td style="text-align:left;"><strong>Memory Model</strong></td><td style="text-align:left;">V8 GC with Buffer segmentation</td><td style="text-align:left;">Zero-cost manual ownership</td><td style="text-align:left;">GC with small stack frames</td><td style="text-align:left;">Manual malloc/free</td></tr><tr><td style="text-align:left;"><strong>Development Speed</strong></td><td style="text-align:left;">Extremely rapid, rich ecosystem</td><td style="text-align:left;">Steep learning curve, strict borrow checker</td><td style="text-align:left;">High speed, built-in concurrency</td><td style="text-align:left;">Slow development, segfault risk</td></tr><tr><td style="text-align:left;"><strong>Zero-Copy Piping</strong></td><td style="text-align:left;">Native <code>stream.pipeline</code></td><td style="text-align:left;">Pointer slicing without copy</td><td style="text-align:left;"><code>io.Copy</code> with buffer pool</td><td style="text-align:left;">Kernel <code>splice()</code> syscalls</td></tr><tr><td style="text-align:left;"><strong>Ecosystem Fit</strong></td><td style="text-align:left;">Shares models with Next.js frontend</td><td style="text-align:left;">Requires FFI or separate binary</td><td style="text-align:left;">Separate binary and toolchain</td><td style="text-align:left;">Separate C/C++ build system</td></tr></tbody></table><ul><li><strong>Why I Used This</strong>: Allows rapid iteration on complex RFC 9111 logic with native Buffer streaming, unified TypeScript types across frontend and proxy, and high I/O throughput [CONFIRM WITH DEVELOPER].</li><li><strong>Why Alternatives Were Rejected</strong>: <ul><li><em>Rust</em>: High implementation complexity for an academic/interview project deadline; Rust stubs maintained in <code>backend/</code> for native acceleration.</li><li><em>Go</em>: Lack of native TypeScript type sharing with Next.js dashboard.</li><li><em>Nginx / Envoy</em>: Rigid configuration languages that make custom request coalescing and dynamic surrogate-tag purging difficult to implement without custom Lua or C++ modules.</li></ul></li><li><strong>30-Second Spoken Interview Answer</strong>:</li></ul><blockquote><p>&quot;I chose Node.js with TypeScript because its non-blocking stream pipeline allows zero-copy piping between client and origin sockets without buffering entire objects into the V8 heap. By relying on native Buffers, we achieve sub-millisecond edge latency while sharing end-to-end type definitions across our proxy engine and Next.js admin dashboard.&quot;</p></blockquote><hr><h2 id="_2-in-memory-cache-storage-architecture" tabindex="-1">2. In-Memory Cache Storage Architecture <a class="header-anchor" href="#_2-in-memory-cache-storage-architecture" aria-label="Permalink to &quot;2. In-Memory Cache Storage Architecture&quot;">​</a></h2><h3 id="chosen-memory-segmented-buffer-store-with-doubly-linked-lru" tabindex="-1">Chosen: Memory-Segmented Buffer Store with Doubly-Linked LRU <a class="header-anchor" href="#chosen-memory-segmented-buffer-store-with-doubly-linked-lru" aria-label="Permalink to &quot;Chosen: Memory-Segmented Buffer Store with Doubly-Linked LRU&quot;">​</a></h3><ul><li><strong>File References</strong>: <code>src/cache/memory-store.ts</code>, <code>src/cache/eviction/lru.ts</code></li><li><strong>Role in Project</strong>: Sub-millisecond L1 cache holding unexpired representations.</li></ul><h3 id="exhaustive-alternatives-comparison-1" tabindex="-1">Exhaustive Alternatives Comparison <a class="header-anchor" href="#exhaustive-alternatives-comparison-1" aria-label="Permalink to &quot;Exhaustive Alternatives Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Evaluation Metric</th><th style="text-align:left;">In-Memory Segments (Chosen)</th><th style="text-align:left;">Redis 7.2</th><th style="text-align:left;">Memcached</th><th style="text-align:left;">RocksDB (Embedded)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Lookup Latency</strong></td><td style="text-align:left;"><strong>&lt; 0.05 ms</strong> (In-process memory)</td><td style="text-align:left;">0.5 - 1.5 ms (Network hop)</td><td style="text-align:left;">0.4 - 1.2 ms (Network hop)</td><td style="text-align:left;">0.2 - 0.8 ms (Disk index)</td></tr><tr><td style="text-align:left;"><strong>Serialization Overhead</strong></td><td style="text-align:left;">Zero (Raw Buffers stored)</td><td style="text-align:left;">Serialization to RESP protocol</td><td style="text-align:left;">Binary protocol serialization</td><td style="text-align:left;">Key/value byte serialization</td></tr><tr><td style="text-align:left;"><strong>Stream Capability</strong></td><td style="text-align:left;">Direct stream slicing</td><td style="text-align:left;">Requires Redis Streams or chunks</td><td style="text-align:left;">Value size capped at 1 MB</td><td style="text-align:left;">Block reads required</td></tr><tr><td style="text-align:left;"><strong>Operational Overhead</strong></td><td style="text-align:left;">None (Embedded in proxy)</td><td style="text-align:left;">Requires Redis cluster &amp; sentinel</td><td style="text-align:left;">Requires Memcached daemon</td><td style="text-align:left;">Requires C++ native binding</td></tr></tbody></table><ul><li><strong>Why I Used This</strong>: An edge proxy requires sub-millisecond response times. Adding a network hop to Redis introduces 1 ms of latency per request, negating the benefit of an edge cache [CONFIRM WITH DEVELOPER].</li><li><strong>When I Would Switch</strong>: When deploying across a cluster of 50+ stateless proxy instances that require a shared central cache tier to maximize hit ratios.</li></ul><hr><h2 id="_3-request-coalescing-thundering-herd-strategy" tabindex="-1">3. Request Coalescing (Thundering Herd) Strategy <a class="header-anchor" href="#_3-request-coalescing-thundering-herd-strategy" aria-label="Permalink to &quot;3. Request Coalescing (Thundering Herd) Strategy&quot;">​</a></h2><h3 id="chosen-in-flight-flight-map-with-leader-follower-stream-fanout" tabindex="-1">Chosen: In-Flight Flight Map with Leader-Follower Stream Fanout <a class="header-anchor" href="#chosen-in-flight-flight-map-with-leader-follower-stream-fanout" aria-label="Permalink to &quot;Chosen: In-Flight Flight Map with Leader-Follower Stream Fanout&quot;">​</a></h3><ul><li><strong>File References</strong>: <code>src/proxy/coalesce.ts</code>, <code>src/proxy/collapsed-forwarding.ts</code></li><li><strong>Role in Project</strong>: Collapses concurrent cache misses into a single upstream request.</li></ul><h3 id="alternatives-comparison" tabindex="-1">Alternatives Comparison <a class="header-anchor" href="#alternatives-comparison" aria-label="Permalink to &quot;Alternatives Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Strategy</th><th style="text-align:left;">In-Flight Map (Chosen)</th><th style="text-align:left;">Redis Distributed Lock</th><th style="text-align:left;">Upstream Queue (RabbitMQ)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Coordination Latency</strong></td><td style="text-align:left;"><strong>Zero</strong> (In-memory lookup)</td><td style="text-align:left;">2 - 5 ms (Redlock consensus)</td><td style="text-align:left;">5 - 15 ms (Message round-trip)</td></tr><tr><td style="text-align:left;"><strong>Stream Fanout</strong></td><td style="text-align:left;">Instant stream tee to all sockets</td><td style="text-align:left;">Polling loop required</td><td style="text-align:left;">Consumer polling required</td></tr><tr><td style="text-align:left;"><strong>Failure Recovery</strong></td><td style="text-align:left;">Leader failure promotes follower</td><td style="text-align:left;">Lock timeout required</td><td style="text-align:left;">Dead-letter retry required</td></tr></tbody></table><hr><h2 id="_4-frontend-administration-dashboard" tabindex="-1">4. Frontend Administration Dashboard <a class="header-anchor" href="#_4-frontend-administration-dashboard" aria-label="Permalink to &quot;4. Frontend Administration Dashboard&quot;">​</a></h2><h3 id="chosen-next-js-14-app-router-tailwindcss-recharts" tabindex="-1">Chosen: Next.js 14 App Router + TailwindCSS + Recharts <a class="header-anchor" href="#chosen-next-js-14-app-router-tailwindcss-recharts" aria-label="Permalink to &quot;Chosen: Next.js 14 App Router + TailwindCSS + Recharts&quot;">​</a></h3><ul><li><strong>File References</strong>: <code>frontend/app/dashboard/page.tsx</code></li><li><strong>Role in Project</strong>: Provides a real-time operational dashboard visualizing hit ratios and latencies.</li></ul><h3 id="alternatives-comparison-1" tabindex="-1">Alternatives Comparison <a class="header-anchor" href="#alternatives-comparison-1" aria-label="Permalink to &quot;Alternatives Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Alternative</th><th style="text-align:left;">Trade-off vs Next.js 14</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Grafana</strong></td><td style="text-align:left;">Pre-built metrics visualization, but lacks interactive controls for custom purge triggers and route edits.</td></tr><tr><td style="text-align:left;"><strong>Plain React Vite SPA</strong></td><td style="text-align:left;">Lacks server-side rendering and unified Next.js API route orchestration.</td></tr><tr><td style="text-align:left;"><strong>Embedded HTML Only</strong></td><td style="text-align:left;">Maintained as lightweight fallback in <code>src/admin/dashboard-html.ts</code>, but lacks interactive charting capabilities.</td></tr></tbody></table>',27)])])}const y=e(l,[["render",o]]);export{u as __pageData,y as default};
